annotations={}
def put(key,purpose,details,inputs='',outputs='',corrupt=''):
    annotations[key]=dict(purpose=purpose,details=details)
    if inputs: annotations[key]['inputs']=inputs
    if outputs: annotations[key]['outputs']=outputs
    if corrupt: annotations[key]['corrupt']=corrupt

