review_path=Path(__file__).parent/'loader/root_review.json'
if review_path.exists():
    review=json.loads(review_path.read_text(encoding='utf-8'))
    for key,fields in review['corrections'].items():
        annotations[key].update(fields)
annotations['O06:B200']['outputs']='объект помечен использованным при любом ответе, после согласия численность добавлена в армию'
annotations['5:7EB6']['corrupt']='HL, DE, BC, AF сохранены, регистр R меняется при исполнении, прерывания остаются запрещёнными'
annotations['5:7EDA']['corrupt']='HL, DE, BC, AF сохранены'
for slot,origin in [(8,0x7D33),(33,0xC000),(34,0xC000)]:
    annotations[f'{slot}:{origin:04X}']['corrupt']="HL, DE, BC, AF, BC', IY после завершения общего распаковщика"
(Path(__file__).parent/'overlay_root_annotations.json').write_text(json.dumps(annotations,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Root annotations',len(annotations))
